#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// Must be UPROPERTY: a raw pointer is invisible to GC and dangles (log 21.05.13 GC, crash 21.05.27).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker is a raw UArenaScoreTracker* without UPROPERTY, so the garbage collector (LogGarbage purge at 21.05.13) freed it; the next goal calls AddPoints on a dangling pointer -> access violation. Fixed with UPROPERTY() TObjectPtr.",
  "no_colors_cause": "DA_Primary (/Game/Data/Palettes) was never cooked: it is only loaded by string path at runtime, bCookAll=False, and only /Game/Data/Effects is in DirectoriesToAlwaysCook. LoadObject returned null (package not found) so the HUD used fallback gray. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
